import sys

def solve(n, a, b, c):
    p = []
    for i in range(n):
        if i == 0:
            if a[i] != b[(i + 1) % n]:
                p.append(a[i])
            elif a[i] != c[(i + 1) % n]:
                p.append(a[i])
        else:
            if a[i] != p[-1] and a[i] != b[(i + 1) % n]:
                pass
            elif b[i] != p[-1] and b[i] != c[(i + 1) % n]:
                p[i - 1], p[i - 2] = p[i - 2], p[i - 1]
            else:
                p[i - 1], p[i - 2] = p[a - 2], p[i - 1]
        if len(p) == i + 1:
            continue
        if a[i] != p[-1]:
            p.append(a[i])
        elif b[i] != p[-1]:
            p.append(b[i])
        else:
            p.append(c[i])
    return p

input = sys.stdin.read().split()
index = 0
t = int(input[index])
index += 1
results = []
for _ in range(t):
    n = int(input[index])
    index += 1
    a = list(map(int, input[index:index + n]))
    index += n
    b = list(map(int, input[index:index + n]))
    index += n
    c = list(map(int, input[index:index + n]))
    index += n

    result = solve(n, a, b, c)
    results.extend(result)

print(' '.join(map(str, results)))
